-- Seed catalog for a given tenant from templates
create or replace function public.seed_catalog(p_tenant uuid)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
set row_security = off
as $$
begin
  insert into public.products (
    tenant_id,
    category,
    subcategory,
    name,
    brand,
    sku,
    unit,
    vat_rate,
    internal_unit_price,
    internal_cost,
    type,
    active,
    tags
  )
  select
    p_tenant,
    category,
    subcategory,
    name,
    brand,
    sku,
    unit,
    vat_rate,
    internal_unit_price,
    internal_cost,
    type,
    active,
    tags
  from public.product_templates
  on conflict (tenant_id, sku) do nothing;
end;
$$;

-- Seed catalog automatically for new tenants
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
set row_security = off
as $$
declare
  v_tenant_id uuid;
  v_company_name text;
begin
  v_company_name := coalesce(new.raw_user_meta_data ->> 'company_name', 'Nouvelle entreprise');

  insert into public.tenants (name)
  values (v_company_name)
  returning id into v_tenant_id;

  insert into public.profiles (id, tenant_id, role, full_name, email)
  values (
    new.id,
    v_tenant_id,
    'admin',
    coalesce(new.raw_user_meta_data ->> 'full_name', ''),
    new.email
  );

  perform public.seed_catalog(v_tenant_id);

  return new;
end;
$$;
